@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @bind="_content" @bind:event="oninput" rows="15" cols="80"></textarea>

<div style="margin-top: 0.5rem;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    @if (_lastSavedAt is not null)
    {
        <span style="margin-left: 1rem;">Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string _content = string.Empty;
    private string _savedContent = string.Empty;
    private DateTime? _lastSavedAt;
    private NotepadInterop? _interop;
    private Timer? _autoSaveTimer;

    private bool HasUnsavedChanges => _content != _savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync();

            var restored = await _interop.LoadAsync();
            if (restored is not null)
            {
                _content = restored;
                _savedContent = restored;
                StateHasChanged();
            }

            _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async void AutoSaveCallback(object? state)
    {
        await InvokeAsync(async () =>
        {
            if (HasUnsavedChanges)
            {
                await SaveAsync();
                StateHasChanged();
            }
        });
    }

    private async Task SaveNowAsync()
    {
        await SaveAsync();
    }

    private async Task SaveAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(_content);
        _savedContent = _content;
        _lastSavedAt = DateTime.Now;
        await _interop.SetUnsavedChangesAsync(false);
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        _content = string.Empty;
        _savedContent = string.Empty;
        _lastSavedAt = null;
        await _interop.ClearAsync();
        await _interop.SetUnsavedChangesAsync(false);
    }

    async ValueTask IAsyncDisposable.DisposeAsync()
    {
        _autoSaveTimer?.Dispose();

        if (_interop is not null)
            await _interop.DisposeAsync();
    }
}

const STORAGE_KEY = 'notepad-content';

let hasUnsavedChanges = false;

function onBeforeUnload(e) {
    if (hasUnsavedChanges) {
        e.preventDefault();
        e.returnValue = '';
    }
}

export function initialize() {
    window.addEventListener('beforeunload', onBeforeUnload);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function setUnsavedChanges(value) {
    hasUnsavedChanges = value;
